<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Jadwal Konten ELSA</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;color:#172339;background:#f4f6fb}*{box-sizing:border-box}body{margin:0}.container{max-width:1100px;margin:0 auto;padding:32px 18px 64px}h1{margin:0;font-size:clamp(25px,4vw,35px);letter-spacing:-.7px}header{margin-bottom:22px;border-bottom:3px solid #514bdb;padding-bottom:18px}.hint{color:#657187;margin-top:7px;font-size:14px}.guide{background:white;border:1px solid #e1e6f0;border-radius:16px;padding:20px 22px;margin-bottom:28px}.guide h2{margin:0 0 16px;font-size:19px}.definitions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.definition{background:#f7f8fc;border:1px solid #ebedf4;border-radius:12px;padding:15px}.definition h3{margin:0 0 7px;font-size:15px}.definition p{margin:0;color:#4e5a6b;line-height:1.55;font-size:13px}.note{margin-top:16px;background:#fff4bb;color:#654b10;border-radius:9px;padding:11px 13px;line-height:1.5;font-size:13px}.day{margin:0 0 25px}.day h2{font-size:19px;margin:0 0 10px}.table-wrap{background:white;border:1px solid #e1e6f0;border-radius:13px;overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left}thead{background:#eaf0fa}th{font-size:12px;color:#52607a;text-transform:uppercase;letter-spacing:.3px;padding:13px 12px;white-space:nowrap}td{border-top:1px solid #e8ebf1;padding:12px;font-size:13px}th:first-child,td:first-child{text-align:center;width:48px}.product{font-weight:700}.type{display:inline-block;font-weight:700;border-radius:6px;padding:5px 9px;font-size:11px;background:#edf0f6}.type.baru{background:#e3efff;color:#275d9e}.type.winning{background:#e4f6eb;color:#1b7651}.without{background:#fff0a0}.without td{border-color:#f4e28b}.rule{font-weight:700;font-size:12px}.without .rule{color:#795200}.with .rule{color:#47705f}@media(max-width:700px){.container{padding:18px 10px 40px}.definitions{grid-template-columns:1fr}.guide{padding:15px}.table-wrap{border-radius:9px}table{min-width:670px}th,td{padding:11px 9px}}@media print{body{background:white}.container{padding:0;max-width:none}.guide,.table-wrap{break-inside:avoid}.day{break-inside:avoid}.without{background:#fff0a0!important;print-color-adjust:exact;-webkit-print-color-adjust:exact}}
</style></head><body><main class="container"><header><h1>Jadwal Upload TikTok — ELSA</h1><p class="hint"><strong>19–24 Oktober 2026</strong> · Senin–Sabtu</p></header><section class="guide"><h2>Penjelasan Jenis Konten</h2><div class="definitions"><article class="definition"><h3>Konten Produk Baru</h3><p>Video satu kali pengambilan (1 take) dengan suara penjelasan atau dubbing. Tujuannya mengenalkan produk baru dan menjelaskan keunggulannya kepada calon pembeli.</p></article><article class="definition"><h3>Konten Winning</h3><p>Video gabungan dari beberapa sudut pengambilan dan cuplikan proses produksi yang sudah tersedia. Tujuannya menjaga penjualan produk yang sudah terbukti laris.</p></article><article class="definition"><h3>Konten Reguler</h3><p>Video dengan konsep bebas dan bisa diunggah dengan atau tanpa keranjang kuning, sesuai jadwal. Tujuannya membuat produk tetap sering terlihat dan dikenal calon pembeli.</p></article></div><div class="note"><strong>Perhatian:</strong> Baris berwarna kuning berarti upload TikTok <strong>tanpa keranjang kuning</strong>. Baris putih berarti upload <strong>dengan keranjang kuning</strong>.</div></section><div id="schedule"></div></main><script>
const records=[{"id": "SENIN-1", "day": "SENIN", "account": "AFFILIATE PLAT", "shop": "KINGPLAT33", "product": "PLAT TIMBUL HOLO", "type": "BARU", "noCart": true}, {"id": "SENIN-2", "day": "SENIN", "account": "AFFILIATE PLAT", "shop": "KINGPLAT33", "product": "PUTIH TIMBUL", "type": "WINNING", "noCart": false}, {"id": "SENIN-3", "day": "SENIN", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "SET ALLAH MUHAMMAD 20 X 20", "type": "BARU", "noCart": false}, {"id": "SENIN-4", "day": "SENIN", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "1SET ISI 3", "type": "WINNING", "noCart": false}, {"id": "SENIN-5", "day": "SENIN", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "1SET BULAT ISI 3", "type": "WINNING", "noCart": false}, {"id": "SENIN-6", "day": "SENIN", "account": "KASIBO", "shop": "ZEUS MODIFY", "product": "MINYAK REM BEAT", "type": "BARU", "noCart": false}, {"id": "SENIN-7", "day": "SENIN", "account": "KASIBO", "shop": "ZEUS MODIFY", "product": "KIJANG", "type": "REGULER", "noCart": false}, {"id": "SELASA-1", "day": "SELASA", "account": "AFFILIATE PLAT", "shop": "KINGPLAT33", "product": "PLAT TIMBUL FONT BARU", "type": "BARU", "noCart": true}, {"id": "SELASA-2", "day": "SELASA", "account": "AFFILIATE PLAT", "shop": "KINGPLAT33", "product": "SEPEDA LISTRIK KOTAK", "type": "REGULER", "noCart": false}, {"id": "SELASA-3", "day": "SELASA", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "SET ALLAH MUHAMMAD 40 X 28,5", "type": "BARU", "noCart": false}, {"id": "SELASA-4", "day": "SELASA", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "SERIBU DINAR", "type": "WINNING", "noCart": false}, {"id": "SELASA-5", "day": "SELASA", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "ALLAH MUHAMMAD TRIPLEK", "type": "REGULER", "noCart": false}, {"id": "SELASA-6", "day": "SELASA", "account": "KASIBO", "shop": "ZEUS MODIFY", "product": "MINYAK REM VARIO", "type": "BARU", "noCart": false}, {"id": "SELASA-7", "day": "SELASA", "account": "KASIBO", "shop": "ZEUS MODIFY", "product": "KIJANG", "type": "REGULER", "noCart": false}, {"id": "RABU-1", "day": "RABU", "account": "AFFILIATE PLAT", "shop": "KINGPLAT33", "product": "PLAT GLOSSY FONT BARU", "type": "BARU", "noCart": true}, {"id": "RABU-2", "day": "RABU", "account": "AFFILIATE PLAT", "shop": "KINGPLAT33", "product": "PUTIH TIMBUL", "type": "WINNING", "noCart": false}, {"id": "RABU-3", "day": "RABU", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "MIHROB V1", "type": "BARU", "noCart": false}, {"id": "RABU-4", "day": "RABU", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "1SET ISI 3", "type": "WINNING", "noCart": false}, {"id": "RABU-5", "day": "RABU", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "1SET BULAT ISI 3", "type": "WINNING", "noCart": false}, {"id": "RABU-6", "day": "RABU", "account": "KASIBO", "shop": "ZEUS MODIFY", "product": "PAUS DARAT", "type": "WINNING", "noCart": false}, {"id": "RABU-7", "day": "RABU", "account": "KASIBO", "shop": "ZEUS MODIFY", "product": "BEAT CANTIK", "type": "REGULER", "noCart": false}, {"id": "KAMIS-1", "day": "KAMIS", "account": "AFFILIATE PLAT", "shop": "KINGPLAT33", "product": "PLAT TIMBUL FAKE", "type": "BARU", "noCart": true}, {"id": "KAMIS-2", "day": "KAMIS", "account": "AFFILIATE PLAT", "shop": "KINGPLAT33", "product": "SEPEDA LISTRIK SEGI 6", "type": "REGULER", "noCart": false}, {"id": "KAMIS-3", "day": "KAMIS", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "SERIBU DINAR", "type": "WINNING", "noCart": false}, {"id": "KAMIS-4", "day": "KAMIS", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "ALLAH MUHAMMAD TRIPLEK", "type": "REGULER", "noCart": false}, {"id": "KAMIS-5", "day": "KAMIS", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "MIHROB V1", "type": "BARU", "noCart": false}, {"id": "KAMIS-6", "day": "KAMIS", "account": "KASIBO", "shop": "ZEUS MODIFY", "product": "HAYABUSA", "type": "REGULER", "noCart": false}, {"id": "KAMIS-7", "day": "KAMIS", "account": "KASIBO", "shop": "ZEUS MODIFY", "product": "MATIC DUNIAWI", "type": "REGULER", "noCart": false}, {"id": "JUMAT-1", "day": "JUMAT", "account": "AFFILIATE PLAT", "shop": "KINGPLAT33", "product": "PLAT TIMBUL FONT BARU", "type": "BARU", "noCart": true}, {"id": "JUMAT-2", "day": "JUMAT", "account": "AFFILIATE PLAT", "shop": "KINGPLAT33", "product": "MOBIL PUTIH GLOSSY", "type": "REGULER", "noCart": true}, {"id": "JUMAT-3", "day": "JUMAT", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "1SET ISI 3", "type": "WINNING", "noCart": false}, {"id": "JUMAT-4", "day": "JUMAT", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "SET ALLAH MUHAMMAD 20 X 20", "type": "BARU", "noCart": false}, {"id": "JUMAT-5", "day": "JUMAT", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "TAUHID AKRILIK", "type": "REGULER", "noCart": false}, {"id": "JUMAT-6", "day": "JUMAT", "account": "KASIBO", "shop": "ZEUS MODIFY", "product": "BEAT PELAN", "type": "REGULER", "noCart": false}, {"id": "JUMAT-7", "day": "JUMAT", "account": "KASIBO", "shop": "ZEUS MODIFY", "product": "BEAT MATIC", "type": "REGULER", "noCart": false}, {"id": "SABTU-1", "day": "SABTU", "account": "AFFILIATE PLAT", "shop": "KINGPLAT33", "product": "PLAT GLOSSY FONT BARU", "type": "BARU", "noCart": true}, {"id": "SABTU-2", "day": "SABTU", "account": "AFFILIATE PLAT", "shop": "KINGPLAT33", "product": "MOBIL PUTIH HOLO", "type": "REGULER", "noCart": true}, {"id": "SABTU-3", "day": "SABTU", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "SERIBU DINAR", "type": "WINNING", "noCart": false}, {"id": "SABTU-4", "day": "SABTU", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "SET ALLAH MUHAMMAD 40 X 28,5", "type": "BARU", "noCart": false}, {"id": "SABTU-5", "day": "SABTU", "account": "HASBI DECOR", "shop": "HASBI DECOR", "product": "ALLAH MUHAMMAD A05", "type": "REGULER", "noCart": false}, {"id": "SABTU-6", "day": "SABTU", "account": "KASIBO", "shop": "ZEUS MODIFY", "product": "ZORO", "type": "REGULER", "noCart": false}, {"id": "SABTU-7", "day": "SABTU", "account": "KASIBO", "shop": "ZEUS MODIFY", "product": "YTTA", "type": "REGULER", "noCart": false}];
const days=['SENIN','SELASA','RABU','KAMIS','JUMAT','SABTU'];
const dates={'SENIN':'19 Oktober 2026','SELASA':'20 Oktober 2026','RABU':'21 Oktober 2026','KAMIS':'22 Oktober 2026','JUMAT':'23 Oktober 2026','SABTU':'24 Oktober 2026'};
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.getElementById('schedule').innerHTML=days.map(day=>{const rows=records.filter(r=>r.day===day);return `<section class="day"><h2>${day.charAt(0)+day.slice(1).toLowerCase()} · ${dates[day]}</h2><div class="table-wrap"><table><thead><tr><th>No.</th><th>Akun TikTok</th><th>Toko Shopee</th><th>Produk</th><th>Jenis Konten</th><th>Upload TikTok</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${r.noCart?'without':'with'}"><td>${i+1}</td><td>${esc(r.account)}</td><td>${esc(r.shop)}</td><td class="product">${esc(r.product)}</td><td><span class="type ${r.type.toLowerCase()}">${r.type==='BARU'?'PRODUK BARU':esc(r.type)}</span></td><td class="rule">${r.noCart?'Tanpa keranjang kuning':'Pakai keranjang kuning'}</td></tr>`).join('')}</tbody></table></div></section>`}).join('');
</script></body></html>